def detect_precise_identification_v2(code: str) -> str:
    tree = ast.parse(code)
    precise_candidates = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            if node.id.startswith(('_', 'is_', 'has_', 'can_', 'should_')):
                precise_candidates.append(f"{node.lineno}: {node.id}")
    return f"Potential precise_identification candidates: {', '.join(precise_candidates[:5])}" if precise_candidates else "No precise_identification candidates found"

